use js_sys::Function;
use wasm_bindgen::prelude::{JsError, JsValue, wasm_bindgen};

use project_x_core::{
    game::projection::NO_NATION,
    hex_map::{HexMap, shape::RectangularHexMapShape},
};
use project_x_procgen::{
    map::{MAX_SEED, MapGenerator, MapGeneratorEvent, MapGeneratorSettings},
    nations::{GeneratedNations, NationsGenerator, NationsGeneratorSettings, PlanetSurface},
};

use crate::wire::NationsReportWire;

/// Planet generated by `procgen_generate_planet`.
///
/// Its tiles are stored row by row from north to south, each row from west to east.
#[wasm_bindgen]
pub struct GeneratedPlanet {
    columns: i16,
    rows: i16,
    elevations: Vec<i16>,
    terrain: Vec<u8>,
    /// What `nations` reads: classified once, with the planet.
    surface: PlanetSurface,
}

#[wasm_bindgen]
impl GeneratedPlanet {
    #[wasm_bindgen(getter)]
    pub fn columns(&self) -> i16 {
        self.columns
    }

    #[wasm_bindgen(getter)]
    pub fn rows(&self) -> i16 {
        self.rows
    }

    /// Elevations of the tiles, in meters. Copied on each access.
    #[wasm_bindgen(getter)]
    pub fn elevations(&self) -> Vec<i16> {
        self.elevations.clone()
    }

    /// `TerrainKind` discriminants of the tiles. Copied on each access.
    #[wasm_bindgen(getter)]
    pub fn terrain(&self) -> Vec<u8> {
        self.terrain.clone()
    }

    /// Settle the planet: `nations` nations, each with its capital, the land it owns on turn 1
    /// and its sphere of influence. The same seed settles the same planet the same way.
    pub fn nations(&self, seed: u32, nations: u16) -> Result<GeneratedNationsView, JsError> {
        self.settle(seed, nations)
            .ok_or_else(|| JsError::new("a planet needs at least one nation"))
    }
}

impl GeneratedPlanet {
    /// `nations`, short of the `JsError`, which cannot be built outside WASM. `None` without any
    /// nation: `NationsGeneratorSettings` would panic, which is unrecoverable in WASM.
    fn settle(&self, seed: u32, nations: u16) -> Option<GeneratedNationsView> {
        if nations == 0 {
            return None;
        }
        let settings = NationsGeneratorSettings::new(u64::from(seed), nations);
        let generated = NationsGenerator::from_settings(settings).generate(&self.surface);
        Some(GeneratedNationsView::from_generated(
            &generated,
            &self.surface,
        ))
    }

    fn from_hex_map(map: &HexMap, settings: &MapGeneratorSettings) -> Self {
        let shape = RectangularHexMapShape::new(settings.get_columns(), settings.get_rows());
        let surface = PlanetSurface::classify(map, settings);
        let elevations = shape
            .coords()
            .map(|coords| map.tile(&coords).expect("missing tile").elevation())
            .collect();
        let terrain = surface.terrain().iter().map(|&kind| kind as u8).collect();
        Self {
            columns: shape.columns(),
            rows: shape.rows(),
            elevations,
            terrain,
            surface,
        }
    }
}

/// The nations of a planet, from `GeneratedPlanet::nations`.
///
/// The tile buffers are laid out like the planet's; the per-nation ones are in `NationId` order.
/// Every getter copies into a typed array, so read each one once.
#[wasm_bindgen]
pub struct GeneratedNationsView {
    tile_sphere: Vec<u16>,
    tile_owner: Vec<u16>,
    capitals: Vec<u32>,
    site_scores: Vec<f32>,
    report: String,
}

#[wasm_bindgen]
impl GeneratedNationsView {
    /// Nation whose sphere of influence holds each tile, `0xFFFF` where none.
    #[wasm_bindgen(getter, js_name = tileSphere)]
    pub fn tile_sphere(&self) -> Vec<u16> {
        self.tile_sphere.clone()
    }

    /// Nation owning each tile on turn 1, `0xFFFF` where none.
    #[wasm_bindgen(getter, js_name = tileOwner)]
    pub fn tile_owner(&self) -> Vec<u16> {
        self.tile_owner.clone()
    }

    /// Row-major tile index of each nation's capital.
    #[wasm_bindgen(getter)]
    pub fn capitals(&self) -> Vec<u32> {
        self.capitals.clone()
    }

    /// Habitability of each nation's capital site.
    #[wasm_bindgen(getter, js_name = siteScores)]
    pub fn site_scores(&self) -> Vec<f32> {
        self.site_scores.clone()
    }

    /// `NationsReportWire` as JSON: how the siting went.
    #[wasm_bindgen(getter)]
    pub fn report(&self) -> String {
        self.report.clone()
    }
}

impl GeneratedNationsView {
    fn from_generated(generated: &GeneratedNations, surface: &PlanetSurface) -> Self {
        let tile_sphere = generated
            .spheres()
            .owners()
            .iter()
            .map(|owner| owner.map_or(NO_NATION, |nation| nation.raw()))
            .collect();
        let mut tile_owner = vec![NO_NATION; surface.tiles_count()];
        let mut capitals = Vec::with_capacity(generated.nations().len());
        let mut site_scores = Vec::with_capacity(generated.nations().len());
        for nation in generated.nations() {
            for &tile in nation.territory() {
                tile_owner[tile as usize] = nation.id().raw();
            }
            capitals.push(
                surface
                    .index(nation.capital())
                    .expect("a capital is on the map"),
            );
            site_scores.push(nation.site_score() as f32);
        }
        let report = NationsReportWire::from(generated.report());
        Self {
            tile_sphere,
            tile_owner,
            capitals,
            site_scores,
            // a `NationsReportWire` is five integers: it cannot fail to serialize
            report: serde_json::to_string(&report).unwrap_or_else(|_| "{}".to_string()),
        }
    }
}

/// Generate a planet, the seas covering `ocean_coverage` of it, and call `on_progress` with
/// the progress percentage along the way.
#[wasm_bindgen]
pub fn procgen_generate_planet(
    seed: u32,
    columns: i16,
    rows: i16,
    ocean_coverage: f64,
    #[wasm_bindgen(unchecked_param_type = "(percentage: number) => void")] on_progress: &Function,
) -> Result<GeneratedPlanet, JsError> {
    // `MapGeneratorSettings` panics on invalid settings, which is unrecoverable in WASM
    if seed > MAX_SEED {
        return Err(JsError::new(&format!(
            "the seed must be at most {MAX_SEED}"
        )));
    }
    if columns <= 0 || rows <= 0 {
        return Err(JsError::new(
            "the map must have at least one column and one row",
        ));
    }
    if !(0.0..=1.0).contains(&ocean_coverage) {
        return Err(JsError::new("the ocean coverage must be from 0 to 1"));
    }

    // the generator takes its settings, which the generated planet needs in turn
    let settings =
        || MapGeneratorSettings::new(seed, columns, rows).with_ocean_coverage(ocean_coverage);
    let map = MapGenerator::from_settings(settings()).generate(|event| {
        let MapGeneratorEvent::Progress(percentage) = event;
        // informational only: an error thrown by the callback does not stop the generation
        let _ = on_progress.call1(&JsValue::NULL, &JsValue::from(percentage));
    });
    Ok(GeneratedPlanet::from_hex_map(&map, &settings()))
}

#[cfg(test)]
mod tests {
    use project_x_core::hex_map::{coordinates::OffsetCoords, shape::RectangularHexMapShape};
    use project_x_procgen::map::{MapGenerator, MapGeneratorSettings, TerrainClassifier};

    use super::GeneratedPlanet;
    use crate::wire::NationsReportWire;

    #[test]
    fn test_generated_planet_stores_tiles_row_by_row() {
        let (seed, columns, rows) = (7, 6, 5);
        let settings = MapGeneratorSettings::new(seed, columns, rows);
        let map = MapGenerator::from_settings(MapGeneratorSettings::new(seed, columns, rows))
            .generate(|_| {});
        let planet = GeneratedPlanet::from_hex_map(&map, &settings);

        assert_eq!((planet.columns(), planet.rows()), (columns, rows));
        assert_eq!(planet.surface.tiles_count(), 30);
        assert_eq!(planet.elevations().len(), 30);
        assert_eq!(planet.terrain().len(), 30);
        let classifier = TerrainClassifier::new(&settings);
        for coords in RectangularHexMapShape::new(columns, rows).coords() {
            let offset = OffsetCoords::from(coords);
            let index = (offset.row() * columns + offset.col()) as usize;
            let elevation = map.tile(&coords).expect("missing tile").elevation();
            assert_eq!(planet.elevations()[index], elevation, "{offset:?}");
            assert_eq!(
                planet.terrain()[index],
                classifier.classify(offset, elevation) as u8,
                "{offset:?}"
            );
        }
    }

    #[test]
    fn test_generated_planet_settles_its_nations() {
        let settings = MapGeneratorSettings::new(3, 24, 16);
        let map =
            MapGenerator::from_settings(MapGeneratorSettings::new(3, 24, 16)).generate(|_| {});
        let planet = GeneratedPlanet::from_hex_map(&map, &settings);
        let nations = planet.settle(3, 3).expect("valid settings");

        assert_eq!(nations.tile_sphere().len(), 24 * 16);
        assert_eq!(nations.tile_owner().len(), 24 * 16);
        assert_eq!(nations.capitals().len(), 3);
        assert_eq!(nations.site_scores().len(), 3);
        for (nation, &capital) in nations.capitals().iter().enumerate() {
            assert_eq!(nations.tile_owner()[capital as usize], nation as u16);
            assert_eq!(nations.tile_sphere()[capital as usize], nation as u16);
            assert!(planet.surface.is_land(capital));
        }
        // owned land lies within the spheres
        for (owner, sphere) in nations.tile_owner().iter().zip(nations.tile_sphere()) {
            if *owner != super::NO_NATION {
                assert_eq!(*owner, sphere);
            }
        }
        let report: NationsReportWire =
            serde_json::from_str(&nations.report()).expect("the report is JSON");
        assert_eq!(report.unplaced, 0);

        assert!(planet.settle(3, 0).is_none(), "no nation at all");
    }
}
